# test_store_order.py

import pytest
from http import HTTPStatus

@pytest.mark.parametrize("order_id, expected_status", [
    (999, HTTPStatus.OK),  # Valid ID
    (1001, HTTPStatus.BAD_REQUEST),  # Invalid ID
    ("abc", HTTPStatus.BAD_REQUEST),  # Non-integer ID
    (123456, HTTPStatus.NOT_FOUND),  # Non-existent ID
])
def test_delete_order(api_client, order_id, expected_status):
    """
    Test the deletion of a purchase order by identifier.
    
    - Valid IDs (< 1000) should return 200 OK.
    - Invalid IDs (> 1000 or non-integers) should return 400 Bad Request.
    - Non-existent IDs should return 404 Not Found.
    """
    endpoint = f"store/order/{order_id}"
    response = api_client.get(endpoint)
    assert response.status_code == expected_status

    if response.status_code == HTTPStatus.OK:
        assert response.json().get('message') == 'order deleted'
    elif response.status_code == HTTPStatus.BAD_REQUEST:
        assert response.json().get('message') == 'Invalid ID supplied'
    elif response.status_code == HTTPStatus.NOT_FOUND:
        assert response.json().get('message') == 'Order not found'
    else:
        assert response.json().get('message') == 'Unexpected error'

def test_delete_order_with_invalid_auth(api_client, invalid_api_key):
    """
    Test deletion with invalid authentication.
    """
    endpoint = "store/order/999"
    headers = {'Authorization': f'Bearer {invalid_api_key}'}
    response = api_client.get(endpoint, headers=headers)
    assert response.status_code == HTTPStatus.UNAUTHORIZED

def test_delete_order_without_auth(api_client):
    """
    Test deletion without authentication.
    """
    endpoint = "store/order/999"
    response = api_client.get(endpoint)
    assert response.status_code == HTTPStatus.UNAUTHORIZED

